from PIL import Image, ImageDraw, ImageOps
im = Image.open('radiograph.jpg').convert('L')
def gridded(name, x1,y1,x2,y2, s=2.5):
    c = ImageOps.autocontrast(im.crop((x1,y1,x2,y2)), cutoff=0.3).convert('RGB')
    c = c.resize((int(c.width*s), int(c.height*s)), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for gx in range(x1, x2, 50):
        px = int((gx-x1)*s)
        if gx % 100 == 0:
            d.line([(px,0),(px,c.height)], fill=(255,80,80), width=1)
            d.text((px+2, 3), str(gx), fill=(255,255,0))
        else:
            d.line([(px,0),(px,c.height)], fill=(120,255,120), width=1)
    for gy in range(y1, y2, 50):
        py = int((gy-y1)*s)
        if gy % 100 == 0:
            d.line([(0,py),(c.width,py)], fill=(255,80,80), width=1)
            d.text((3, py+2), str(gy), fill=(255,255,0))
        else:
            d.line([(0,py),(c.width,py)], fill=(120,255,120), width=1)
    c.save(f'/tmp/{name}.png')
gridded('uR_grid', 520, 330, 820, 580)
gridded('uL_grid', 1780, 330, 2080, 580)
print('ok')
EOF", "description": "Fine 50px grids over upper molar regions"}
